import * as THREE from 'three';
// Shared layout keeps decorative instruments solid and the central experiment routes clear.
export const SCIENCE_LAB_LAYOUT=Object.freeze({bench:{x:-3.7,z:1,width:2.4,depth:1.10},sink:{x:-5.02,z:-.5,width:.85,depth:1.30},storage:{x:4.70,z:.65,width:1.30,depth:1.25},stool:{x:-3.7,z:2.52,radius:.56,seatTop:.64}});
export const SCIENCE_LAB_OBSTACLES=Object.entries(SCIENCE_LAB_LAYOUT).map(([id,p])=>({x:p.x,z:p.z,hx:p.radius??p.width/2+.03,hz:p.radius??p.depth/2+.08}));
export const SCIENCE_STOOL={id:'science.lab-stool',roomId:'science',at:{x:-2.25,z:2.30},anchor:{x:-3.7,z:2.30,yaw:Math.PI},seatTop:.64};
export function buildScienceLabProps({root,box,cylinder,sphere,beam,mat,label}){
 const group=name=>{const g=new THREE.Group();g.name='science.'+name;root.add(g);return g;};
 const bench=group('observation-bench'),b=SCIENCE_LAB_LAYOUT.bench;box(b.width,.15,b.depth,'#b8c9bf',b.x,1.03,b.z,.07,bench);box(b.width+.04,.055,b.depth+.04,'#4d6b65',b.x,1.13,b.z,.035,bench);for(const dx of[-1.02,1.02])for(const dz of[-.4,.4])box(.12,.96,.12,'#8ba69b',b.x+dx,.50,b.z+dz,.025,bench);box(1.56,.09,.60,'#a5b6a6',b.x,.36,b.z,.035,bench);for(const [i,c]of['#d3ba8e','#f5e8ce'].entries())box(.68,.09,.40,c,b.x+.20,.44+i*.10,b.z,.018,bench);
 // Decorative microscope: recognizable C-arm, stage, revolving objectives and angled eyepiece.
 const microscope=group('microscope'),x=-4.25,z=.92;box(.60,.075,.49,'#edead8',x,1.205,z,.055,microscope);const arm=new THREE.CatmullRomCurve3([new THREE.Vector3(x+.18,1.24,z-.09),new THREE.Vector3(x+.27,1.50,z-.09),new THREE.Vector3(x+.11,1.87,z-.09),new THREE.Vector3(x-.09,1.92,z-.09)]);microscope.add(new THREE.Mesh(new THREE.TubeGeometry(arm,22,.06,9,false),mat('#dfdfcf')));beam([x-.09,1.92,z-.09],[x-.10,1.83,z+.03],.12,'#dfdfcf',microscope);box(.51,.045,.39,'#4b6662',x,1.49,z+.03,.02,microscope);box(.22,.015,.11,'#b8d9d5',x-.03,1.525,z+.08,.008,microscope);cylinder(.09,.10,.09,'#657f79',x-.10,1.77,z+.06,microscope);for(const dx of[-.07,.05])cylinder(.027,.035,.16,'#95b2ac',x+dx-.10,1.66,z+.06,microscope);beam([x-.10,1.83,z+.03],[x-.26,2.05,z+.13],.12,'#d9ddcc',microscope);beam([x-.26,2.05,z+.13],[x-.31,2.12,z+.16],.10,'#49685e',microscope);const knob=cylinder(.075,.075,.075,'#718f84',x+.28,1.62,z+.02,microscope);knob.rotation.z=Math.PI/2;
 const glassware=group('glassware');const glass=new THREE.MeshStandardMaterial({color:'#c8e4de',transparent:true,opacity:.55,roughness:.15,side:THREE.DoubleSide});function vessel(px,pz,r,h,color){const profile=[[r*.78,0],[r*.94,.025],[r,h],[r*.82,h],[r*.76,.055],[0,.055]].map(p=>new THREE.Vector2(...p));const v=new THREE.Mesh(new THREE.LatheGeometry(profile,20),glass);v.position.set(px,1.17,pz);glassware.add(v);cylinder(r*.73,r*.73,h*.30,color,px,1.22+h*.15,pz,glassware);for(let i=1;i<=3;i++)box(r*.5,.012,.012,'#719995',px+r*.13,1.20+h*i/4,pz+r+.007,.002,glassware);}
 vessel(-3.22,1.23,.17,.42,'#e4c67b');vessel(-2.78,.86,.13,.32,'#91c4b9');box(.63,.055,.27,'#cba879',-3.23,1.20,.72,.025,glassware);box(.63,.055,.27,'#cba879',-3.23,1.44,.72,.025,glassware);for(const dx of[-.25,.25])box(.055,.25,.055,'#b9966d',-3.23+dx,1.32,.72,.014,glassware);for(const [i,c]of['#accbd0','#d4bf8b','#a9cba4'].entries()){const tube=new THREE.Mesh(new THREE.CylinderGeometry(.045,.045,.38,12,1,true),glass);tube.position.set(-3.41+i*.18,1.45,.72);glassware.add(tube);sphere(.045,c,-3.41+i*.18,1.27,.72,1,1,1,glassware);cylinder(.034,.034,.13,c,-3.41+i*.18,1.32,.72,glassware);}
 const sink=group('sink'),s=SCIENCE_LAB_LAYOUT.sink;box(s.width,.93,s.depth,'#9fb8aa',s.x,.49,s.z,.06,sink);box(s.width+.02,.095,s.depth+.02,'#e6e5d5',s.x,1.0,s.z,.045,sink);const basinProfile=[[.02,-.13],[.14,-.13],[.24,-.07],[.28,.015],[.34,.045],[.34,.005],[.28,-.025],[.23,-.13],[.13,-.18],[.02,-.18]].map(p=>new THREE.Vector2(...p));const basin=new THREE.Mesh(new THREE.LatheGeometry(basinProfile,28),mat('#d3dfd3'));basin.name='science.sink-bowl';basin.position.set(s.x,1.20,s.z);basin.scale.z=1.45;sink.add(basin);cylinder(.04,.04,.01,'#66837d',s.x,1.076,s.z,sink);const faucet=new THREE.CatmullRomCurve3([new THREE.Vector3(s.x-.32,1.04,s.z),new THREE.Vector3(s.x-.32,1.47,s.z),new THREE.Vector3(s.x-.12,1.52,s.z),new THREE.Vector3(s.x-.04,1.34,s.z)]);sink.add(new THREE.Mesh(new THREE.TubeGeometry(faucet,20,.026,7,false),mat('#9eb9b3')));box(.11,.20,.13,'#d0e0c6',s.x+.22,1.18,s.z-.43,.022,sink);box(.14,.03,.07,'#638c79',s.x+.22,1.30,s.z-.43,.01,sink);
 const cabinet=group('safety-storage'),p=SCIENCE_LAB_LAYOUT.storage;for(const dx of[-p.width/2+.045,p.width/2-.045])box(.09,1.98,p.depth,'#acc0af',p.x+dx,1.02,p.z,.025,cabinet);box(p.width, .10,p.depth,'#b8cbb7',p.x,2.01,p.z,.025,cabinet);box(p.width,.08,p.depth,'#acc0af',p.x,.06,p.z,.025,cabinet);box(p.width-.12,1.9,.065,'#688578',p.x,1.02,p.z-p.depth/2+.0325,.015,cabinet);for(const y of[.82,1.41])box(p.width-.12,.055,p.depth-.10,'#d8dcc5',p.x,y,p.z+.02,.018,cabinet);for(const dx of[-.35,.33]){const goggles=new THREE.Group();cabinet.add(goggles);for(const e of[-.115,.115]){const rim=new THREE.Mesh(new THREE.TorusGeometry(.10,.021,7,18),mat('#d9c792'));rim.position.set(p.x+dx+e,1.68,p.z+.44);goggles.add(rim);const lens=new THREE.Mesh(new THREE.CircleGeometry(.079,16),glass);lens.position.set(p.x+dx+e,1.68,p.z+.451);goggles.add(lens);}beam([p.x+dx-.026,1.68,p.z+.44],[p.x+dx+.026,1.68,p.z+.44],.02,'#d9c792',goggles);}for(const[i,c]of['#d5b991','#e1d8b8','#bdd3bd'].entries()){box(.27,.34,.33,c,p.x-.37+i*.36,1.06,p.z+.30,.03,cabinet);box(.16,.07,.012,'#f4ebd3',p.x-.37+i*.36,1.12,p.z+.474,.003,cabinet);}for(const dx of[-.33,.33]){box(.53,.52,.03,'#c6d3bf',p.x+dx,.39,p.z+.644,.025,cabinet);box(.11,.035,.045,'#7a9584',p.x+dx,.48,p.z+.68,.01,cabinet);}label('보안경 · 도구',p.x,2.23,p.z+.45,1.45,'#385d4e','#e9e2c9',cabinet);
 const stool=group('lab-stool'),c=SCIENCE_LAB_LAYOUT.stool;cylinder(c.radius,c.radius,.14,'#c5ae7d',c.x,c.seatTop-.07,c.z,stool);for(let i=0;i<4;i++){const a=Math.PI/4+i*Math.PI/2;beam([c.x+Math.cos(a)*.38,.06,c.z+Math.sin(a)*.38],[c.x+Math.cos(a)*.30,.55,c.z+Math.sin(a)*.30],.075,'#789487',stool);}const rest=new THREE.Mesh(new THREE.TorusGeometry(.37,.025,6,24),mat('#91a99a'));rest.rotation.x=Math.PI/2;rest.position.set(c.x,.27,c.z);stool.add(rest);
 return{bench,microscope,glassware,sink,cabinet,stool};
}
